// ---- edit these once after import ----
const CONFIG = {
  model: 'anthropic/claude-sonnet-5',            // any OpenRouter model id
  fallbackModels: ['anthropic/claude-sonnet-4.6'], // OpenRouter tries these if the first is down
  telegramChatId: 'YOUR_TELEGRAM_CHAT_ID',
};

// Webhook payload = alert published by the Glue streaming job (via SQS -> Lambda).
// De-duplicate on alert_id for 6 hours: SQS/Lambda delivery is at-least-once.
const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};
const now = Date.now();
for (const [k, ts] of Object.entries(staticData.seen)) if (now - ts > 6 * 3600e3) delete staticData.seen[k];

const out = [];
for (const item of $input.all()) {
  const a = item.json.body || item.json;
  const id = a.alert_id || item.json.headers?.['idempotency-key'];
  if (!a.rule || (id && staticData.seen[id])) continue;
  if (id) staticData.seen[id] = now;
  out.push({ json: { alert: a, config: CONFIG,
    needs_triage: ['PAYMENT_FAILURE_SPIKE', 'PAYMENT_METHOD_DEGRADED'].includes(a.rule) } });
}
return out;

