const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const results = [];
const inputs = $input.all();
for (let i = 0; i < inputs.length; i++) {
  // Items arrive either straight from 'Needs LLM triage?' (false branch) or from OpenRouter;
  // for the latter, walk the paired-item lineage back to the normalized alert.
  const base = inputs[i].json.alert ? inputs[i].json : ($('Normalize + dedupe').itemMatching(i)?.json ?? {});
  const a = base.alert || {};
  let triage = null;
  const content = inputs[i].json.choices?.[0]?.message?.content;
  if (content) { try { triage = JSON.parse(content); } catch (e) { triage = { title: content.slice(0, 200) }; } }

  const icon = a.severity === 'critical' ? '🔴' : '🟠';
  const m = a.metrics || {};
  let text = `${icon} <b>${esc(a.rule)}</b> (${esc(a.severity)})\n${esc(a.summary)}\n`;
  text += `<i>window ${esc(a.window_start)} · ${esc(a.dimension)}</i>\n`;
  if (m.top_failure_code) text += `top failure: <code>${esc(m.top_failure_code)}</code>\n`;
  if (triage) {
    text += `\n🤖 <b>${esc(triage.title || 'LLM triage')}</b>\n`;
    for (const c of (triage.likely_causes || [])) text += `• ${esc(c)}\n`;
    if (triage.customer_impact) text += `Impact: ${esc(triage.customer_impact)}\n`;
    for (const s of (triage.next_actions || [])) text += `→ ${esc(s)}\n`;
    if (triage.escalate) text += `\n⚠️ <b>Escalate to gateway / bank partner</b>`;
  } else if (base.needs_triage) {
    text += `\n(LLM triage unavailable - raw alert only)`;
  }
  results.push({ json: { chat_id: base.config?.telegramChatId, text, silent: a.severity !== 'critical' } });
}
return results;
